/*
 © 2024-2026 Captain Compliance
 www.captaincompliance.com

 Consent-Mode-native GTM template:
 1. setDefaultConsentState (region-scoped, non-essential denied by default)
 2. injectScript the Captain Compliance banner (loads the CMP UI + geo/GPC)
 3. updateConsentState from the captainComplianceConsent event / cookie
*/

const log = require('logToConsole');
const injectScript = require('injectScript');
const encode = require('encodeUriComponent');
const makeInteger = require('makeInteger');
const JSON = require('JSON');
const getCookieValues = require('getCookieValues');
const copyFromDataLayer = require('copyFromDataLayer');
const addConsentListener = require('addConsentListener');
const setDefaultConsentState = require('setDefaultConsentState');
const updateConsentState = require('updateConsentState');
const gtmOnSuccess = data.gtmOnSuccess;
const gtmOnFailure = data.gtmOnFailure;

// ---- config ----------------------------------------------------------------
// GTM's sandboxed JS does not support regex literals, so trim trailing
// slashes with a small loop (a regex-based strip fails the sandbox import).
const baseUrl = (function (url) {
  while (url.charAt(url.length - 1) === '/') {
    url = url.substring(0, url.length - 1);
  }
  return url;
})(data.bannerBaseUrl || 'https://api-prod.cptn.co');
const eventName = data.dataLayerEventName || 'captainComplianceConsent';
const cookieName = data.consentCookieName || 'cc_consent_preference';
const enableConsentMode = data.enableConsentMode !== false;
const honorGpc = data.honorGpc !== false;

// The browser's own GPC signal at Consent Initialization. Waiting for the
// banner script (injected below, loads async) meant GPC only applied after
// Container Loaded, so tags on earlier triggers fired for GPC visitors. The
// sandbox cannot read navigator, so it arrives through a GTM variable that
// returns navigator.globalPrivacyControl (the "GPC signal variable" field).
const browserGpc = honorGpc && (data.gpcSignal === true || data.gpcSignal === 'true');

// Captain Compliance category -> Google Consent Mode v2 signals.
// personalization_storage is a preferences/personalization signal (e.g. site
// recommendations), NOT advertising - it follows the Functionality choice.
// ad_personalization is the advertising one and stays with the ad signals.
const AD_SIGNALS = ['ad_storage', 'ad_user_data', 'ad_personalization'];
const ANALYTICS_SIGNALS = ['analytics_storage'];
const FUNCTIONALITY_SIGNALS = ['functionality_storage', 'personalization_storage'];

// cc_region_defaults is written by the edge consent-defaults script as e.g.
// F1P1T0 (Functionality, Performance, Targeting). Anything else is ignored.
function readRegionDefaults() {
  const raw = getCookieValues('cc_region_defaults');
  if (!raw || !raw.length) return null;
  const v = raw[0];
  if (v.length !== 6 || v.charAt(0) !== 'F' || v.charAt(2) !== 'P' || v.charAt(4) !== 'T') return null;
  return { f: v.charAt(1) === '1', p: v.charAt(3) === '1', t: v.charAt(5) === '1' };
}

// ---- 1. default consent state ---------------------------------------------
if (enableConsentMode) {
  const scope = data.consentScope || 'regions';
  const waitMs = makeInteger(data.waitForUpdate) || 500;

  // Non-essential storage denied; essential (security) always granted.
  const deniedDefault = {
    ad_storage: 'denied',
    ad_user_data: 'denied',
    ad_personalization: 'denied',
    analytics_storage: 'denied',
    functionality_storage: 'denied',
    personalization_storage: 'denied',
    security_storage: 'granted',
    wait_for_update: waitMs
  };
  const grantedDefault = {
    ad_storage: 'granted',
    ad_user_data: 'granted',
    ad_personalization: 'granted',
    analytics_storage: 'granted',
    functionality_storage: 'granted',
    personalization_storage: 'granted',
    security_storage: 'granted'
  };

  if (browserGpc) {
    // GPC means "reject all non-essential" while the signal is on, wherever the
    // visitor is, matching the banner (it locks Targeting, Performance and
    // Functionality off under GPC). One global denied default, no region
    // grants, so no region rule can grant ahead of the banner.
    setDefaultConsentState(deniedDefault);
  } else if (scope === 'captain') {
    // One region list: the banner's own, resolved with our geolocation instead
    // of Google's. The edge script stores this visitor's regional defaults in
    // cc_region_defaults, so after the first page view they apply here
    // synchronously. On the first page view, deny and let the edge script
    // (injected below, a few hundred bytes) send the update while Google tags
    // hold for wait_for_update.
    const stored = readRegionDefaults();
    if (stored) {
      setDefaultConsentState({
        ad_storage: stored.t ? 'granted' : 'denied',
        ad_user_data: stored.t ? 'granted' : 'denied',
        ad_personalization: stored.t ? 'granted' : 'denied',
        analytics_storage: stored.p ? 'granted' : 'denied',
        functionality_storage: stored.f ? 'granted' : 'denied',
        personalization_storage: stored.f ? 'granted' : 'denied',
        security_storage: 'granted'
      });
    } else {
      setDefaultConsentState(deniedDefault);
    }
    injectScript(
      baseUrl + '/banner/consent-defaults?access-token=' + encode(data.accessToken),
      function () {},
      function () { log('[CaptainCompliance] consent defaults could not load; denied default stands.'); },
      'ccConsentDefaults'
    );
  } else if (scope === 'global_optout') {
    // Allow everywhere until the visitor opts out (US-style).
    setDefaultConsentState(grantedDefault);
  } else if (scope === 'global_optin') {
    // Deny non-essential everywhere until the visitor consents.
    setDefaultConsentState(deniedDefault);
  } else if (scope === 'regions_optout') {
    // Opt-out in the listed regions (granted there); opt-in everywhere else
    // (denied). Inverse of the 'regions' branch below - use it to go opt-in
    // globally except a few opt-out regions (e.g. the U.S.).
    let optOutRegions = [];
    if (data.requiredRegions) {
      optOutRegions = data.requiredRegions.split(',').map(function (r) {
        return r.trim();
      }).filter(function (r) {
        return r.length > 0;
      });
    }
    if (optOutRegions.length === 0) {
      // No opt-out regions listed: deny non-essential everywhere (opt-in).
      setDefaultConsentState(deniedDefault);
    } else {
      // Global default FIRST, region-specific override LAST. Google resolves
      // each region to its most-specific default and a later region-scoped
      // call must win over the earlier global one, so deny globally first,
      // then grant the listed (opt-out) regions. (Doing region-first then a
      // global call last let the global default clobber the region rule.)
      setDefaultConsentState(deniedDefault);
      grantedDefault.region = optOutRegions;
      setDefaultConsentState(grantedDefault);
    }
  } else {
    // Specific regions: deny in the listed regions, allow elsewhere.
    let regions = [];
    if (data.requiredRegions) {
      regions = data.requiredRegions.split(',').map(function (r) {
        return r.trim();
      }).filter(function (r) {
        return r.length > 0;
      });
    }
    if (regions.length === 0) {
      // Region mode with no regions listed: fall back to deny everywhere.
      setDefaultConsentState(deniedDefault);
    } else {
      // Global default FIRST, region-specific override LAST (see regions_optout
      // above): grant everywhere, then deny the listed (opt-in) regions so the
      // region rule wins there and the global grant holds elsewhere.
      setDefaultConsentState(grantedDefault);
      deniedDefault.region = regions;
      setDefaultConsentState(deniedDefault);
    }
  }

  if (data.adsDataRedaction) {
    // Signalled to Google tags via gtag; exposed for completeness.
    log('[CaptainCompliance] ads_data_redaction requested (configure on the Google tag).');
  }
  if (data.urlPassthrough) {
    log('[CaptainCompliance] url_passthrough requested (configure on the Google tag).');
  }
}

// ---- consent mapping helpers ----------------------------------------------
function applyGrant(signals, state, granted) {
  for (let i = 0; i < signals.length; i++) {
    state[signals[i]] = granted ? 'granted' : 'denied';
  }
}

// Read consent from the dataLayer event payload, falling back to the cookie.
function readSelectedCookies(eventData) {
  if (eventData && eventData.selectedCookies) {
    return eventData.selectedCookies;
  }
  const raw = getCookieValues(cookieName);
  if (raw && raw.length) {
    const parsed = JSON.parse(raw[0]);
    if (parsed && parsed.selectedCookies) {
      return parsed.selectedCookies;
    }
  }
  return null;
}

function readGpc(eventData) {
  if (browserGpc) {
    return true;
  }
  if (eventData && (eventData.gpc === true || eventData.globalPrivacyControl === true)) {
    return true;
  }
  const raw = getCookieValues(cookieName);
  if (raw && raw.length) {
    const parsed = JSON.parse(raw[0]);
    if (parsed && (parsed.gpc === true || parsed.globalPrivacyControl === true)) {
      return true;
    }
  }
  return false;
}

function pushUpdate(eventData) {
  if (!enableConsentMode) return;
  const selected = readSelectedCookies(eventData);
  // Under GPC there is nothing to wait for: everything non-essential is denied
  // whatever is (or is not) stored.
  if (!selected && !(honorGpc && readGpc(eventData))) return;

  const perf = !!selected && selected.PERFORMANCE_COOKIES === true;
  const targeting = !!selected && selected.TARGETING_COOKIES === true;
  const functionality = !!selected && selected.FUNCTIONALITY_COOKIES === true;

  // Honor GPC the way the banner does: Targeting, Performance and
  // Functionality all denied while the signal is present.
  const gpc = honorGpc && readGpc(eventData);

  const update = { security_storage: 'granted' };
  applyGrant(ANALYTICS_SIGNALS, update, perf && !gpc);
  applyGrant(AD_SIGNALS, update, targeting && !gpc);
  applyGrant(FUNCTIONALITY_SIGNALS, update, functionality && !gpc);

  updateConsentState(update);
  log('[CaptainCompliance] updateConsentState', update);
}

// ---- 3. update consent on banner event / listener -------------------------
if (enableConsentMode) {
  // Fire once for consent that already exists at container load.
  const existing = copyFromDataLayer(eventName);
  if (existing) {
    pushUpdate(existing);
  } else {
    pushUpdate(null); // try the cookie
  }

  // React to later consent changes pushed by the banner.
  addConsentListener('ad_storage', function () {
    pushUpdate(copyFromDataLayer(eventName));
  });
}

// ---- 2. inject the Captain Compliance banner (loads early) ----------------
const bannerUrl = baseUrl + '/banner/script?accessToken=' + encode(data.accessToken);
injectScript(bannerUrl, gtmOnSuccess, gtmOnFailure, 'ccBanner');


